[
  {
    "enabled": true,
    "name": "Aimlock By Fxy ♻️",
    "url": [
      "*/GetBackpack",
      "*/assetindexer",
      "*/fileinfo",
      "*/ABHotUpdates/*",
      "*/ver*",
      "*/CheckHackBehavior",
      "*/GetMatchmakingBlacklist"
    ],
    "script": "async function onResponse(context, request, response) {\n  const url = request.url;\n  \n  // \n  const HEX_ANTENA_MAX = \"\";\n  const HEX_AIMLOCK_CORE = \"\";\n\n  if (url.includes('/CheckHackBehavior') || url.includes('/GetMatchmakingBlacklist')) {\n    response.statusCode = 403;\n    response.body = 'OK';\n    return response;\n  }\n\n  function htb(hex) {\n    let clean = hex.replace(/[^0-9a-fA-F]/g, '');\n    let bytes = '';\n    for (let i = 0; i < clean.length; i += 2) {\n      bytes += String.fromCharCode(parseInt(clean.substr(i, 2), 16));\n    }\n    return bytes;\n  }\n\n  try {\n    if (url.includes('/ABHotUpdates') || url.includes('/ver')) {\n      let modified = false;\n      let bodyObj = {};\n      try {\n        bodyObj = JSON.parse(response.body);\n        modified = true;\n      } catch(e) {\n        if (typeof response.body === 'string') {\n          let textData = response.body;\n          textData = textData.replace(/recoil_factor\\s*=\\s*[0-9.]+/g, \"recoil_factor=0.0\");\n          textData = textData.replace(/aim_stabilizer\\s*=\\s*[0-9.]+/g, \"aim_stabilizer=1.0\");\n          response.body = textData;\n          return response;\n        }\n      }\n      if (modified && bodyObj) {\n        bodyObj.device_tuning = {\n          \"touch_hz_boost\": 120,\n          \"sampling_rate_multiplier\": 2.0,\n          \"aim_assist_lock\": \"head\",\n          \"anti_recoil_level\": 100,\n          \"stabilization\": true\n        };\n        response.body = JSON.stringify(bodyObj);\n        return response;\n      }\n    }\n\n    if (url.includes('/GetBackpack') && request.method === 'POST') {\n      if (HEX_AIMLOCK_CORE !== \"\") {\n        response.statusCode = 200;\n        response.headers['Content-Type'] = 'application/octet-stream';\n        response.body = htb(HEX_AIMLOCK_CORE);\n        if (response.headers['Content-Length']) delete response.headers['Content-Length'];\n        return response;\n      }\n    }\n\n    if (url.includes('/assetindexer') || url.includes('/fileinfo')) {\n      if (HEX_ANTENA_MAX !== \"\") {\n        response.statusCode = 200;\n        response.headers['Content-Type'] = 'application/octet-stream';\n        response.body = htb(HEX_ANTENA_MAX);\n        if (response.headers['Content-Length']) delete response.headers['Content-Length'];\n        return response;\n      }\n    }\n  } catch (err) {\n    return response;\n  }\n  return response;\n}"
  }
]